#!/usr/bin/env python3
"""HarborPass JSON command-line application."""
import json
import sys
from datetime import date, timedelta


def make_release_1_0_notice(account):
    """Approved release 1.0 values, frozen for support case IOS-1842."""
    credit_cents = 0
    if account["autopay"] and account["completed_years"] >= 2:
        credit_cents = min(account["plan_cents"] // 10, 2400)
    send_on = date.fromisoformat(account["renewal_on"]) - timedelta(days=21)
    return {
        "customer_id": account["customer_id"],
        "send_on": send_on.isoformat(),
        "credit_cents": credit_cents,
        "amount_due_cents": account["plan_cents"] - credit_cents,
    }


def make_notice(account):
    """Current customer-facing policy; future changes belong here."""
    credit_cents = 0
    if account["completed_years"] >= 3:
        credit_cents = min(account["plan_cents"] * 15 // 100, 3600)
    send_on = date.fromisoformat(account["renewal_on"]) - timedelta(days=14)
    return {
        "customer_id": account["customer_id"],
        "send_on": send_on.isoformat(),
        "credit_cents": credit_cents,
        "amount_due_cents": account["plan_cents"] - credit_cents,
    }


def csv_field(value):
    value = str(value)
    if any(character in value for character in ',"\r\n'):
        return '"' + value.replace('"', '""') + '"'
    return value


def export_notices(accounts):
    columns = ("customer_id", "send_on", "credit_cents", "amount_due_cents")
    rows = [",".join(columns)]
    for account in accounts:
        notice = make_notice(account)
        rows.append(",".join(csv_field(notice[column]) for column in columns))
    return {"csv": "\n".join(rows) + "\n", "count": len(accounts)}


def batch_notices(on, accounts):
    notices = []
    for account in accounts:
        notice = make_notice(account)
        if notice["send_on"] == on:
            notices.append(notice)
    return {
        "on": on,
        "notices": notices,
        "total_due_cents": sum(notice["amount_due_cents"] for notice in notices),
    }


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "HarborPass"}
    if request.get("command") == "notice":
        return make_notice(request["account"])
    if request.get("command") == "export":
        return export_notices(request["accounts"])
    if request.get("command") == "batch":
        return batch_notices(request["on"], request["accounts"])
    if request.get("command") == "support_replay":
        return {
            "case_id": request["case_id"],
            "notice": make_release_1_0_notice(request["account"]),
        }
    return {"error": "unknown_command"}


def main():
    request = json.load(sys.stdin)
    response = handle(request)
    json.dump(response, sys.stdout)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
# HarborPass renewal CLI

HarborPass sells annual memberships. This project is a small local JSON application. It requires Python 3.9 or later and no packages or network access.

Run `python3 main.py` with one JSON request on standard input. The program writes one JSON response to standard output. Currently `{"command":"ping"}` returns `{"status":"ok","product":"HarborPass"}`; an unrecognized command returns `{"error":"unknown_command"}`. JSON key order and surrounding JSON whitespace do not matter.

Run the starter tests with `python3 -m unittest discover -s tests -v`. Each product issue is accompanied by a public JSON examples file. Run those examples with `python3 test_public.py --cases /path/to/stage_N.json`. Feature examples for an earlier stage can become obsolete when a later issue explicitly changes its business requirements; the issue history remains available to explain prior releases.

Accounts use customer_id (nonempty string), renewal_on (valid Gregorian YYYY-MM-DD from 2020-01-01 through 2099-12-31), plan_cents (nonnegative integer US cents), completed_years (nonnegative integer), and autopay (boolean). A notice contains customer_id, send_on, credit_cents, and amount_due_cents. Account collections preserve order and duplicate customer IDs. Inputs to the exercises are well formed. No current clock, locale, or remote data is needed.

Send `{"command":"notice","account":ACCOUNT}` to generate a current renewal notice. For every renewal date, the notice is dated 14 calendar days before renewal. Members with at least 3 completed years receive a credit of 15% of their plan price, rounded down to whole cents and capped at 3600 cents. Autopay does not affect eligibility. All other members receive zero credit. The amount due is the plan price minus the credit.

Send `{"command":"export","accounts":[ACCOUNT,...]}` to export the current notices as `{"csv":STRING,"count":N}`. The CSV columns are `customer_id,send_on,credit_cents,amount_due_cents`, with one row per account in input order, including duplicate IDs. The header and each row end with LF, including for an empty collection. Fields are quoted only if they contain a comma, double quote, CR, or LF; internal double quotes are doubled.

Send `{"command":"support_replay","case_id":"IOS-1842","account":ACCOUNT}` to reproduce the approved release 1.0 preview as `{"case_id":"IOS-1842","notice":NOTICE}`. This case always sends notices 21 calendar days before renewal and awards members with autopay enabled and at least 2 completed years a credit of 10% of the plan price, rounded down to whole cents and capped at 2400 cents; other members receive zero credit. The amount due is the plan price minus the credit. These historical rules remain frozen when current notice and export policies change. IOS-1842 is the only supported case.

Send `{"command":"batch","on":"YYYY-MM-DD","accounts":[ACCOUNT,...]}` to collect the current notices scheduled for that day. The response is `{"on":"YYYY-MM-DD","notices":[NOTICE,...],"total_due_cents":N}`. It copies `on` unchanged and includes each account exactly when its current notice's `send_on` equals `on`, preserving input order and repeated IDs. Each included notice is complete, and `total_due_cents` sums their amounts due. Empty results contain `notices: []` and `total_due_cents: 0`.

Implement product issues in their supplied order. Source code, docs, tests, and prior issue text remain available throughout the sequence.
import json
from pathlib import Path
import subprocess
import sys
import unittest

ROOT = Path(__file__).resolve().parents[1]


class SmokeTests(unittest.TestCase):
    def call(self, request):
        result = subprocess.run([sys.executable, str(ROOT / "main.py")], input=json.dumps(request), capture_output=True, text=True, check=True, timeout=3)
        return json.loads(result.stdout)

    def test_ping(self):
        self.assertEqual(self.call({"command": "ping"}), {"status": "ok", "product": "HarborPass"})

    def test_unknown_command(self):
        self.assertEqual(self.call({"command": "not_a_command"}), {"error": "unknown_command"})

    def test_notice_credit(self):
        cases = [
            (19999, 3, True, 2999),
            (19999, 3, False, 2999),
            (19999, 2, True, 0),
            (19999, 2, False, 0),
            (19999, 1, True, 0),
            (19999, 0, False, 0),
            (90000, 8, True, 3600),
            (90000, 8, False, 3600),
            (23999, 3, False, 3599),
            (24000, 3, True, 3600),
            (24010, 3, False, 3600),
            (0, 3, True, 0),
            (6, 3, False, 0),
            (7, 3, True, 1),
            (10**30 + 1, 3, False, 3600),
        ]
        for plan, years, autopay, credit in cases:
            with self.subTest(plan=plan, years=years, autopay=autopay):
                account = {
                    "customer_id": "M-17", "renewal_on": "2026-04-15",
                    "plan_cents": plan, "completed_years": years, "autopay": autopay,
                }
                self.assertEqual(self.call({"command": "notice", "account": account}), {
                    "customer_id": "M-17", "send_on": "2026-04-01",
                    "credit_cents": credit, "amount_due_cents": plan - credit,
                })

    def test_notice_calendar_dates(self):
        cases = [
            ("2020-01-01", "2019-12-18"),
            ("2024-02-29", "2024-02-15"),
            ("2024-03-14", "2024-02-29"),
            ("2025-03-14", "2025-02-28"),
            ("2099-12-31", "2099-12-17"),
        ]
        for renewal_on, send_on in cases:
            with self.subTest(renewal_on=renewal_on):
                account = {
                    "customer_id": "calendar-member", "renewal_on": renewal_on,
                    "plan_cents": 100, "completed_years": 0, "autopay": False,
                }
                self.assertEqual(self.call({"command": "notice", "account": account}), {
                    "customer_id": "calendar-member", "send_on": send_on,
                    "credit_cents": 0, "amount_due_cents": 100,
                })

    def test_batch_filter_order_duplicates_and_total(self):
        accounts = [
            {"customer_id": "Z", "renewal_on": "2026-04-15",
             "plan_cents": 19999, "completed_years": 3, "autopay": False},
            {"customer_id": "excluded", "renewal_on": "2026-04-22",
             "plan_cents": 10000, "completed_years": 9, "autopay": True},
            {"customer_id": "A", "renewal_on": "2026-04-15",
             "plan_cents": 90000, "completed_years": 8, "autopay": True},
            {"customer_id": "Z", "renewal_on": "2026-04-15",
             "plan_cents": 500, "completed_years": 2, "autopay": True},
        ]
        accounts.append(accounts[0].copy())
        self.assertEqual(self.call({
            "command": "batch", "on": "2026-04-01", "accounts": accounts,
        }), {
            "on": "2026-04-01",
            "notices": [
                {"customer_id": "Z", "send_on": "2026-04-01",
                 "credit_cents": 2999, "amount_due_cents": 17000},
                {"customer_id": "A", "send_on": "2026-04-01",
                 "credit_cents": 3600, "amount_due_cents": 86400},
                {"customer_id": "Z", "send_on": "2026-04-01",
                 "credit_cents": 0, "amount_due_cents": 500},
                {"customer_id": "Z", "send_on": "2026-04-01",
                 "credit_cents": 2999, "amount_due_cents": 17000},
            ],
            "total_due_cents": 120900,
        })

    def test_batch_empty_results(self):
        account = {
            "customer_id": "M-17", "renewal_on": "2026-04-15",
            "plan_cents": 100, "completed_years": 0, "autopay": False,
        }
        for accounts in ([], [account]):
            with self.subTest(accounts=accounts):
                self.assertEqual(self.call({
                    "command": "batch", "on": "2026-04-02", "accounts": accounts,
                }), {"on": "2026-04-02", "notices": [], "total_due_cents": 0})

    def test_batch_calendar_dates_match_notice(self):
        for renewal_on, on in [
            ("2020-01-01", "2019-12-18"),
            ("2024-03-14", "2024-02-29"),
            ("2025-03-14", "2025-02-28"),
            ("2099-12-31", "2099-12-17"),
        ]:
            with self.subTest(renewal_on=renewal_on):
                account = {
                    "customer_id": 'M-é,"\n', "renewal_on": renewal_on,
                    "plan_cents": 0, "completed_years": 3, "autopay": False,
                }
                notice = self.call({"command": "notice", "account": account})
                self.assertEqual(self.call({
                    "command": "batch", "on": on, "accounts": [account],
                }), {"on": on, "notices": [notice], "total_due_cents": 0})

    def test_export_empty(self):
        self.assertEqual(self.call({"command": "export", "accounts": []}), {
            "csv": "customer_id,send_on,credit_cents,amount_due_cents\n",
            "count": 0,
        })

    def test_export_csv_quoting(self):
        cases = [
            ("plain", "plain"),
            (" space \t", " space \t"),
            ("M-é", "M-é"),
            ("a,b", '"a,b"'),
            ('a"b', '"a""b"'),
            ("a\rb", '"a\rb"'),
            ("a\nb", '"a\nb"'),
            ('a,"\r\nb', '"a,""\r\nb"'),
        ]
        for customer_id, encoded_id in cases:
            with self.subTest(customer_id=customer_id):
                account = {
                    "customer_id": customer_id, "renewal_on": "2026-04-15",
                    "plan_cents": 19999, "completed_years": 3, "autopay": False,
                }
                self.assertEqual(self.call({"command": "export", "accounts": [account]}), {
                    "csv": "customer_id,send_on,credit_cents,amount_due_cents\n"
                           + encoded_id + ",2026-04-01,2999,17000\n",
                    "count": 1,
                })

    def test_export_order_duplicates_and_notice_values(self):
        accounts = [
            {"customer_id": "Z", "renewal_on": "2020-01-01",
             "plan_cents": 90000, "completed_years": 8, "autopay": False},
            {"customer_id": "A", "renewal_on": "2024-03-21",
             "plan_cents": 0, "completed_years": 0, "autopay": False},
            {"customer_id": "Z", "renewal_on": "2025-03-21",
             "plan_cents": 19999, "completed_years": 2, "autopay": True},
        ]
        self.assertEqual(self.call({"command": "export", "accounts": accounts}), {
            "csv": "customer_id,send_on,credit_cents,amount_due_cents\n"
                   "Z,2019-12-18,3600,86400\n"
                   "A,2024-03-07,0,0\n"
                   "Z,2025-03-07,0,19999\n",
            "count": 3,
        })


if __name__ == "__main__":
    unittest.main()
